// Read-only release verification. No network, provider, Git or deployment calls.
import fs from'node:fs';import path from'node:path';import assert from'node:assert/strict';import crypto from'node:crypto';import vm from'node:vm';import{execFileSync}from'node:child_process';import{fileURLToPath}from'node:url';
export const CORPUS='e15e64b25fd01798e0430c8af886b7bdd37961d3607a061a0dba7941bd318358';
export const PROFILE='7755e9f34ddf7ae17c7912a3eabddd5971a9fbb650a1e32ef47dfcc0a5d21ba6';
const hash=v=>crypto.createHash('sha256').update(typeof v==='string'||v instanceof Uint8Array?v:JSON.stringify(v)).digest('hex');
export function verifyRelease(root,{read=f=>fs.readFileSync(path.join(root,f)),archive}={}){
 const prefix='assistant/releases/2026-11-06/',json=f=>JSON.parse(read(f)),release=json(prefix+'RELEASE.json');assert.equal(release.status,'RELEASED_AND_LIVE_VERIFIED');assert.equal(release.deployId,'6aed0124f8a810d9098d6b1b');assert.equal(release.corpusVersion,CORPUS);assert.equal(release.profileHash,PROFILE);
 for(const[f,digest]of Object.entries(release.payloadHashes)){assert(!path.isAbsolute(f)&&!f.split('/').includes('..'));assert.equal(hash(read(prefix+f)),digest,'Released payload drift '+f);}
 const corpus=json(prefix+'corpus.json'),profile=json(prefix+'production-profile.json');assert.equal(hash(corpus.documents),CORPUS);assert.equal(hash(corpus),'d882ec2693f0c72b1199cdca4fcee0e946018e02cb5832a69eb976451738acae');assert.equal(corpus.documents.length,775);assert.equal(corpus.documents.reduce((n,d)=>n+d.facts.length,0),6814);assert.equal(hash(profile),PROFILE);assert.equal(profile.boundCorpusVersion,CORPUS);assert.equal(profile.activationApproved,true);for(const k of['knowledge','privacy','spending','launch'])assert.equal(profile.ownerApprovals[k],true,k);
 assert.equal(profile.allowance.dayBudgetUsd,1);assert.equal(profile.allowance.monthBudgetUsd,30);assert.equal(profile.budgetStoreName,'oz-assistant-production-budget-v1');assert.equal(profile.budgetStoreRegion,'us-east-2');assert.equal(profile.apiKeyVariable,'OZ_ASSISTANT_OPENAI_API_KEY');assert.equal(profile.candidateModelId,'gpt-6-luna');
 for(const[f,digest]of Object.entries(release.runtimeSources))assert.equal(hash(read(f)),digest,'Runtime differs from deployed '+f);for(const[f,digest]of Object.entries(release.clientSources))assert.equal(hash(read(f)),digest,'Client differs from deployed '+f);
 const previous='Oz Timber Floor uses your details to respond to product, service and project enquiries. Hidden source and attribution fields stay in place so the team can understand where the enquiry came from.',next='Oz Timber Floor uses your product, service and project details to respond to your enquiry.';
 // Git contains source HTML, not the prior package's generated shared header.
 // Pin both independently; compare the copy-only edit against the sealed prior
 // deployment, rather than incorrectly equating source and published HTML.
 const contacts={
  'contact.html':{source:'dba9f225d4c5f7d400413718ab9619653c5ddd7ebc36adcaf33fee0d5756995d',previous:'692a93489d687718e8f8c44e19ff146936c07449530130ed97f3a58d98f6dde3',deployed:'9b574b4d92cf99fe3bdb608b083c3e306e1fcff0089caa3a692dc179ec7804c7'},
  'contact/index.html':{source:'77ed2cb5dc315e21dcb2679a1af08cac181bf6a7d7665bddc4bf8acb913b6ceb',previous:'5331bdeb3a06468da49f07838e7f898fdc257f46cc5d02e5aa6c38cb249a806d',deployed:'28503781762c9c74f1c80b7abcf4062575884aa17405381bd790a3c4f752e510'}
 };
 for(const[f,pins]of Object.entries(contacts)){const source=read(f),overlay=read(prefix+'public/'+f).toString();assert.equal(hash(source),pins.source,'Source contact changed');assert.equal(hash(overlay),pins.deployed,'Released contact changed');assert.equal(overlay.split(next).length,2);assert.equal(hash(overlay.replace(next,previous)),pins.previous,'Contact overlay exceeds reviewed paragraph from previous deployment');}
 assert.equal(json('assistant/config/production.json').activationApproved,false,'Do not change source default activation for a Git sync');assert.match(read('assets/flooring-assistant-config.js').toString(),/enabled: false/);
 const raw=read(prefix+'corpus.json').toString();assert(!/supplierSourceUrl|supplierId|sourceTag|wholesale|supabase|operon|\.codex|\/Users\/|\.env|(?<![\w-])sk-[A-Za-z0-9_-]{20,}/i.test(raw));const builder=read('scripts/build-public-package.mjs').toString();const allow=builder.match(/const publicDirectories = Object\.freeze\(\[([\s\S]*?)\]\)/);assert(allow);assert(!/["']assistant["']/.test(allow[1]),'Private release must not be publicly copied');
 if(archive){assert.equal(hash(fs.readFileSync(archive)),release.assistantZipSha256);const code=execFileSync('unzip',['-p',archive,'netlify/functions/flooring-assistant.mjs'],{encoding:'utf8',maxBuffer:8e6}),literal=name=>{const m=code.match(new RegExp('^var '+name+' = ([\\s\\S]+?);\\n','m'));assert(m);return JSON.parse(JSON.stringify(vm.runInNewContext('('+m[1]+')',Object.create(null),{timeout:1000})));};assert.deepEqual(literal('corpus_default'),corpus);assert.deepEqual(literal('production_default'),profile);}
 return{status:'EXACT_DEPLOYED_CHATBOT_RELEASE_PASS',deployId:release.deployId,corpusVersion:CORPUS,profileHash:PROFILE,monthlyUsd:30,dailyUsd:1,archiveChecked:!!archive,networkCalls:0,deployments:0};
}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){const root=path.resolve(import.meta.dirname,'..');console.log(JSON.stringify(verifyRelease(root,{archive:process.env.OZ_DEPLOYED_ASSISTANT_ZIP})));}
